import re


def title_of(html: str) -> str:
    """Return the text between the first `<title>` and the next `</title>`.

    The tag names are matched case-insensitively, but only the exact forms
    `<title>` and `</title>` are recognised (no attributes). The text is
    returned verbatim, without stripping whitespace and including any
    newlines or other markup inside it. Returns an empty string when there
    is no `<title>`, when no `</title>` follows it, or when the title is
    empty. Works purely on the given string and does no I/O.
    """
    m = re.search(
        r"<title>(.*?)</title>",
        html,
        flags=re.IGNORECASE | re.DOTALL | re.ASCII,
    )
    if m is None:
        return ""
    return m.group(1)


def test_basic_title() -> None:
    html = "<html><head><title>Hello</title></head><body></body></html>"
    assert title_of(html) == "Hello"


def test_no_title_returns_empty() -> None:
    assert title_of("<html><body>No title here</body></html>") == ""


def test_empty_input() -> None:
    assert title_of("") == ""


def test_empty_title() -> None:
    assert title_of("<title></title>") == ""


def test_case_insensitive_tags() -> None:
    assert title_of("<HTML><TITLE>Upper</TITLE></HTML>") == "Upper"
    assert title_of("<Title>Mixed</tItLe>") == "Mixed"


def test_text_case_preserved() -> None:
    assert title_of("<title>MiXeD Case</title>") == "MiXeD Case"


def test_first_title_only() -> None:
    html = "<title>First</title><title>Second</title>"
    assert title_of(html) == "First"


def test_missing_closing_tag() -> None:
    assert title_of("<html><title>Unclosed<body></body></html>") == ""


def test_closing_tag_only() -> None:
    assert title_of("Stray</title>") == ""


def test_whitespace_preserved() -> None:
    assert title_of("<title>  padded \t</title>") == "  padded \t"


def test_multiline_title() -> None:
    html = "<head><title>Line one\nLine two</title></head>"
    assert title_of(html) == "Line one\nLine two"


def test_title_with_entities_untouched() -> None:
    assert title_of("<title>Tom &amp; Jerry</title>") == "Tom &amp; Jerry"


def test_unicode_title() -> None:
    assert title_of("<title>Café – 日本語</title>") == "Café – 日本語"


def test_title_surrounded_by_other_content() -> None:
    html = "<p>before</p><title>T</title><p>after</p>"
    assert title_of(html) == "T"
